exercises.starter:
SELECT customer_id, id, order_date,
  LAG(order_date) OVER (ORDER BY order_date, id) AS prev_order
FROM orders;

exercises.template:
WITH m AS (
  SELECT strftime('%Y-%m', tx_date) AS month, COUNT(*) AS n
  FROM transactions GROUP BY month
)
SELECT month, n, {{1}}(n, 1, {{2}}) OVER (ORDER BY month) AS prev_n
FROM m ORDER BY month;
